import type { ChorTopic } from "@/content/chor-kaun";
import type { EmojiPuzzle } from "@/content/emoji-picture";
import type { Level } from "@/lib/types";
import { shuffle } from "@/lib/util";
import { getServiceClient } from "../supabase/service";

/**
 * The review bank. Items generated by the model land here as PENDING. Only the owner's approval
 * (content.review) makes them servable. The suggestion route uses approved items as the fallback,
 * before the fixed built-in lists.
 */

const LEVELS_FOR: Record<Level, Level[]> = {
  kids: ["kids"],
  family: ["kids", "family"],
  adults: ["family", "adults"],
};

export async function approvedEmojiPuzzles(level: Level, count: number, avoid: string[]): Promise<EmojiPuzzle[] | null> {
  const db = getServiceClient();
  if (!db) return null;
  try {
    const { data, error } = await db
      .from("content_items")
      .select("data, level")
      .eq("game_id", "emoji-picture")
      .eq("approved", true)
      .eq("rejected", false)
      .limit(500);
    if (error || !data) return null;
    const shown = new Set(avoid.map((a) => a.toLowerCase()));
    const allowed = LEVELS_FOR[level];
    const fresh = data
      .filter((row) => allowed.includes(row.level as Level))
      .map((row) => row.data as EmojiPuzzle)
      .filter((p) => p && typeof p.answer === "string" && !shown.has(p.answer.toLowerCase()));
    if (fresh.length < 3) return null;
    return shuffle(fresh).slice(0, count);
  } catch {
    return null;
  }
}

export async function approvedChorTopic(avoid: string[], excludeIds: string[]): Promise<ChorTopic | null> {
  const db = getServiceClient();
  if (!db) return null;
  try {
    const { data, error } = await db
      .from("content_items")
      .select("data")
      .eq("game_id", "chor-kaun")
      .eq("approved", true)
      .eq("rejected", false)
      .limit(200);
    if (error || !data) return null;
    const shown = new Set(avoid.map((a) => a.toLowerCase()));
    const fresh = data
      .map((row) => row.data as ChorTopic)
      .filter((t) => t && typeof t.label === "string" && Array.isArray(t.words) && !shown.has(t.label.toLowerCase()) && !excludeIds.includes(t.id));
    if (!fresh.length) return null;
    return shuffle(fresh)[0] ?? null;
  } catch {
    return null;
  }
}

export interface PendingItem {
  key: string;
  level: Level;
  data: unknown;
  source: string;
}

/** Stores generated items as pending. Items whose key is already in the bank are skipped. Returns how many were stored. */
export async function insertPending(gameId: string, items: PendingItem[]): Promise<number> {
  const db = getServiceClient();
  if (!db || !items.length) return 0;
  const { data: existing } = await db.from("content_items").select("item_key").eq("game_id", gameId).not("item_key", "is", null);
  const taken = new Set((existing ?? []).map((r) => String(r.item_key).toLowerCase()));
  const rows = items
    .filter((i) => i.key && !taken.has(i.key.toLowerCase()))
    .map((i) => ({ game_id: gameId, level: i.level, data: i.data, source: i.source, approved: false, rejected: false, item_key: i.key.toLowerCase() }));
  if (!rows.length) return 0;
  const { error } = await db.from("content_items").insert(rows);
  return error ? 0 : rows.length;
}
